// ---------------------------------------------------------------------------
// Audio helpers shared by every playback path in Jarvis.
//
// Two problems live here, and both of them are why audio "silently fails":
//
// 1. The TTS action returns a bare ArrayBuffer whose format depends on which
//    provider answered — Groq Orpheus sends WAV, ElevenLabs sends MP3.
//    Handing an MP3 to a Blob typed `audio/wav` makes Safari refuse to play
//    it, so the real type is sniffed from the magic number instead.
//
// 2. Mobile browsers only allow an <audio> element to start playing without a
//    fresh user gesture if that element has already been "unlocked" during
//    one. A fraction of a second of silence played from a click handler arms
//    the whole page for later programmatic playback.
// ---------------------------------------------------------------------------

/** A short silent WAV, used to unlock audio output during a user gesture. */
export const SILENT_WAV =
  "data:audio/wav;base64,";

/** Detect the audio format of raw bytes by magic number. */
export function audioMimeType(buffer: ArrayBuffer): string {
  const view = new Uint8Array(buffer.slice(0, 16));
  const ascii = (start: number, end: number) =>
    String.fromCharCode(...Array.from(view.slice(start, end)));

  if (ascii(0, 4) === "RIFF" && ascii(8, 12) === "WAVE") return "audio/wav";
  if (ascii(0, 4) === "OggS") return "audio/ogg";
  if (ascii(4, 8) === "ftyp") return "audio/mp4";
  if (ascii(0, 3) === "ID3") return "audio/mpeg";
  if (view.length >= 2 && view[0] === 0xff && (view[1] & 0xe0) === 0xe0) {
    return "audio/mpeg";
  }
  if (view[0] === 0x1a && view[1] === 0x45 && view[2] === 0xdf) {
    return "audio/webm";
  }
  if (ascii(0, 4) === "fLaC") return "audio/flac";
  return "audio/mpeg";
}

/**
 * Arm audio output for the rest of the session. Call this from inside the user
 * gesture that starts audio (the Live Mode button, a sound chip, a tap on a
 * play button) — never from a timer or a network callback.
 */
export async function unlockAudioElement(): Promise<void> {
  try {
    const el = new Audio(SILENT_WAV);
    el.volume = 0;
    await el.play();
    el.pause();
  } catch {
    // Still blocked by the autoplay policy — the browser will prompt, or the
    // caller falls back to speech synthesis. Nothing else to do.
  }
}

// ---------------------------------------------------------------------------
// UI chimes, synthesised on the fly.
//
// Acknowledgement sounds are tiny, fixed and used constantly, so generating
// them with two oscillators is cheaper than shipping audio files — and it
// means the wake tone can never 404 or bloat the bundle.
// ---------------------------------------------------------------------------

let chimeCtx: AudioContext | null = null;

function getChimeContext(): AudioContext | null {
  try {
    if (chimeCtx && chimeCtx.state !== "closed") return chimeCtx;
    const Ctor =
      window.AudioContext ??
      (window as unknown as { webkitAudioContext: typeof AudioContext })
        .webkitAudioContext;
    chimeCtx = new Ctor();
    return chimeCtx;
  } catch {
    return null;
  }
}

/** Short two-note "I'm listening" chime. Resolves when it finishes. */
export function playAckChime(volume = 0.12): void {
  const ctx = getChimeContext();
  if (!ctx) return;
  void ctx.resume().catch(() => {});

  const now = ctx.currentTime;
  // E6 → A6: a rising perfect fifth reads as "acknowledged" without being loud.
  const notes = [
    { freq: 1318.51, at: 0, dur: 0.09 },
    { freq: 1760.0, at: 0.085, dur: 0.16 },
  ];

  for (const note of notes) {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(note.freq, now + note.at);
    // A short attack/decay envelope stops the click a raw gate would make.
    gain.gain.setValueAtTime(0.0001, now + note.at);
    gain.gain.exponentialRampToValueAtTime(volume, now + note.at + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + note.at + note.dur);
    osc.connect(gain).connect(ctx.destination);
    osc.start(now + note.at);
    osc.stop(now + note.at + note.dur + 0.02);
  }
}
